def base(title,desc,body,path='index.html',active='home',structured=None):
 depth=path.count('/')
 prefix='../'*depth
 title=escape(title,quote=True); desc=escape(desc,quote=True)
 ld=structured or {}
 ldstr=f'<script type="application/ld+json">{json.dumps(ld,ensure_ascii=False).replace("</","<\\/")}</script>' if ld else ''
 return f'''<!DOCTYPE html><html lang="en-US"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#174bb3"><meta name="description" content="{desc}"><title>{title}</title><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><meta property="og:locale" content="en_US"><link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/style.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@600;700;800&family=DM+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">{ldstr}</head><body>{header(prefix,active)}<main id="main">{body}</main>{footer(prefix)}<script src="{prefix}assets/site.js" defer></script></body></html>'''

